import{_ as r,l,o as e,c as s,v as o,p as c,x as i,d,i as n,S as b}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"bio","description":"","frontmatter":{"title":"bio","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bio-block.md","filePath":"cs/bio-block.md","lastUpdated":1789023840000}'),p={name:"cs/bio-block.md"};function m(h,a,_,u,f,E){const t=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="bio" tabindex="-1">bio <a class="header-anchor" href="#bio" aria-label="Permalink to &quot;bio&quot;">​</a></h1><div class="epigraph"><p>bio 描述一次块 I/O：目标设备偏移、方向、以及一组页加页内偏移的分散聚集列表。</p><footer>—— 据 Bovet and Cesati 对 Linux bio 的叙述；Tanenbaum 对块设备接口的整理</footer></div><p><a href="/cs/blk-mq">上一课</a>有了队列，还没有请求长什么样。<a href="/cs/page-cache">页缓存</a> 里的页不一定物理连续，也不一定整页对应整块。<a href="/cs/vfs">VFS</a> 的 <code>readpage</code>/<code>writepages</code> 必须把「这些帧」交给块层。缺口是 <strong>bio</strong>：与文件系统布局无关的块 I/O 描述符。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若驱动只接受单段连续物理缓冲，页 Cache 每次都要 bounce。缺口：bio 持有 bio_vec 数组（页、偏移、长度），扇区起点，读或写，完成回调。块层可把 bio 合并进更大的 request，或拆到设备限制。文件系统不谈门铃寄存器；驱动不谈 inode。下一课 DMA 才把 vec 变成总线地址。</p><p>本课不把每个 <code>bi_opf</code> 标志背完。</p><p><span class="marginnote">一个 writepages 可能提交多个 bio。完成回调在下半部上下文：清页锁、结束缓冲、唤醒 fsync 等待者。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ext4 等：把脏页填进 bio，指向该 inode 的块号（经 bmap），<code>submit_bio</code> 进 blk-mq。设备完成：回调标记页最新或错误。用户 <code>read</code> 的拷贝发生在页已 uptodate 之后，不是 bio 里直接指向用户缓冲（Direct I/O 例外，本课点名即可）。</p>',9)),(e(),c(b,null,{default:i(()=>[n(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAGES%5B%22%E9%A1%B5%20Cache%20%E4%B8%AD%E7%9A%84%E9%A1%B5%22%5D%20--%3E%20VEC%5B%22bio_vec%20%E5%88%86%E6%95%A3%E8%81%9A%E9%9B%86%22%5D%0A%20%20VEC%20--%3E%20SUB%5B%22submit_bio%22%5D%0A%20%20SUB%20--%3E%20MQ%5B%22blk-mq%22%5D%0A%20%20MQ%20--%3E%20CB%5B%22%E5%AE%8C%E6%88%90%E5%9B%9E%E8%B0%83%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>bio 是 FS 与设备之间的契约：字节在页里，位置在扇区里。它让 <a href="/cs/demand-paging">按需调页</a> 的 major 缺页与 writeback 走同一提交函数。不要把 bio 写成 SCSI CDB 百科。错误向上变成 <code>read</code> 的 EIO 或映射文件上的信号，接口裂缝在 mmap 课已点过。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 multi-page folio 的全部改名。不保证所有驱动支持任意长度的 vec。下一课：设备如何按物理地址搬这些页——PIO 与 DMA。</p><p>后课默认：块请求已是页的分散聚集。控制器成为总线主设备，下一课 I/O 与 DMA。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>bio 用页向量描述块读写，对接页 Cache 与 blk-mq。</li><li>完成走回调；FS 与驱动在此分界。</li><li>搬动物理字节是 DMA 课的缺口。</li><li>出处：Bovet and Cesati, <em>ULK</em>；Tanenbaum <em>MOS</em>；Linux block 层文档。</li></ul>',7))])}const k=r(p,[["render",m]]);export{B as __pageData,k as default};
